def is_Isomorphic(s1, s2):
    # If lengths of two strings are not equal, they cannot be isomorphic
    if len(s1) != len(s2):
        return False
    char_map1, char_map2 = {}, {}
    for char1, char2 in zip(s1, s2):
        # If a character in s1 is already mapped to a character in s2
        if char1 in char_map1 and char_map1[char1] != char2:
            return False
        # If a character in s2 is already mapped to a character in s1
        if char2 in char_map2 and char_map2[char2] != char1:
            return False
        # Mapping a character in s1 to a character in s2
        char_map1[char1] = char2
        char_map2[char2] = char1
    return True
