    """Check if a number is not prime. A non-prime number has factors other than 1 and itself."""

    # Check for numbers less than 2 (not prime)
    if n <= 1:
        return True

    # Check for numbers divisible by 2 (even numbers except 2)
    if n % 2 == 0:
        return True

    # Check if n is divisible by any odd number starting from 3
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return True

    return False
```

