import heapq
def nth_super_ugly_number(n, primes):
    def get_next(primes): # This function returns the next ugly number
        uglies = set()
        for prime in primes:
            uglies.add(prime)
            uglies.update(uglies | {ugly * prime for ugly in uglies if ugly * prime <= n})
        return sorted(uglies)[1]
    if len(primes) == 1: return primes[0] * n // min(primes) + 1
    hp = [get_next(primes) for _ in range(len(primes))]
    heapq.heapify(hp)
    for _ in range(n - 1):
        last = heapq.heappop(hp)
        nxt = get_next(primes) 
        if nxt == last: heapq.heappush(hp, nxt)
        else: heapq.heapreplace(hp, nxt)
    return heapq.heappop(hp)
