```python
def count_Pairs(arr, n):
    # Create a count array to keep track of elements
    count = [0] * n

    # Store the frequency of each element in the array
    for i in arr:
        count[i - 1] += 1

    # Initialize counter
    unequal_pairs = 0

    # Calculate the number of unequal pairs
    for i in range(n):
        if count[i] > 1:
            unequal_pairs += count[i] * (count[i] - 1) // 2

    # Adjust the counter for each pair count
    for i in range(1, n):
        unequal_pairs += count[i] * i

    # Adjust for pairs who's count is more than once
    for i in range(n - 1):
        if count[i] > 1 and count[i + 1] > 1:
            unequal_pairs -= count[i] * count[i + 1] // 2

    return unequal_pairs
```

