def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def Sum(n):
    """Find the sum of all prime divisors of a given number."""
    prime_sum = 0
    for i in range(2, n + 1):
        while n % i == 0 and is_prime(i):
            prime_sum += i
            n //= i
    return prime_sum

