def max_product(arr):
    """
    Finds a pair with the highest product in the given array of integers.

    Parameters:
    arr (list): A list of integers.

    Returns:
    tuple: A tuple containing the pair with the highest product and the product itself.
    """
    if len(arr) < 2:
        return "Array should contain at least two elements."

    max1, max2 = arr[0], arr[1]
    min1, min2 = arr[0], arr[1]

    for num in arr[2:]:
        if num > max1:
            max2, max1 = max1, num
        elif num > max2:
            max2 = num

        if num < min1:
            min2, min1 = min1, num
        elif num < min2:
            min2 = num

    return (max1, max2) if max1 * max2 >= max1 * min2 else (min1, min2)
