def is_abundant(n):
    total_factors = 1  # 1 is a factor of every number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total_factors += i + n // i
            # If n is a perfect square, we've counted the root twice, so subtract it if it's a perfect square
            if i == n // i:
                total_factors -= i
    return total_factors > n
