from typing import List

def count_duplic(a: List[int]) -> tuple:
    # Initialize empty lists to store results
    repeated_indices = []
    max_length = 0

    # Iterate over the list to find consecutive duplicates
    current_length = 1
    for i in range(1, len(a)):
        if a[i] == a[i-1]:
            current_length += 1
        else:
            # If the current length is greater than the maximum, update max_length and repeated_indices
            if current_length > max_length:
                max_length = current_length
                repeated_indices = [i - max_length + 1, i]
            current_length = 1

    # Append the final sequence if any
    if current_length > max_length:
        max_length = current_length
        repeated_indices = [i - max_length + 1, i]

    return ([a[x] for x in range(repeated_indices[0], repeated_indices[1] + 1)], max_length)
