def modular_sum(arr, n, m):
    # Initialize a boolean matrix dp
    dp = [[False for _ in range(m+1)] for _ in range(n+1)]

    # Base case: If the sum is 0, there is always a subset
    for i in range(n+1):
        dp[i][0] = True

    # Build the dp table
    for i in range(1, n+1):
        for j in range(1, m+1):
            # If the current element is greater than the target modulo m, skip it
            if arr[i-1] > j:
                dp[i][j] = dp[i-1][j]
            else:
                # Include or exclude the current element
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]

    # If there is a subset with sum divisible by m, return True
    return dp[n][m]
```

