import numpy as np

def maxAverageOfPath(matrix, n):
    # Convert the matrix to a numpy array for efficient array operations
    mat = np.array(matrix)
    # Initialize the result with negative infinity
    result = float('-inf')
    # Iterate over all possible starting positions
    for i in range(n):
        for j in range(n):
            # Iterate over all possible ending positions
            for k in range(i, n):
                for l in range(j, n):
                    # Calculate the average of the submatrix
                    avg = np.mean(mat[i:k+1, j:l+1])
                    # Update the result if the current average is greater
                    if avg > result:
                        result = avg
    return result
```

