def get_noOfways(n):
    # Base case: if n is 0 or 1, there's only 1 way to tile the floor
    if n == 0 or n == 1:
        return 1
    # Recursive case: the number of ways to tile the floor of n 
    # is the sum of the ways to tile the floor of n-1 and n-2
    else:
        return get_noOfways(n-1) + get_noOfways(n-2)
