def min_Swaps(b_str1, b_str2):
    n = len(b_str1)
    for i in range(n):
        j = i
        while j < n and b_str1[j] != b_str2[i]:
            j += 1
        if j == n:
            return -1
        while j > i:
            b_str1[j], b_str1[j-1] = b_str1[j-1], b_str1[j]
            j -= 1
    return 0
```

