import math

def count_Fac(num):
    def prime_factors(n):
        i = 2
        count = 0
        while i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                count += 1
        return count

    max_prime = math.isqrt(num)  # Efficient to seek limit till square root of num
    prime_counts = []
    for i in range(2, max_prime + 1):
        if num % i:
            continue
        num = num // i
        prime_counts.append(prime_factors(i))

    # Count all distinct numbers across all prime factors found
    return len(set(prime_counts))
```
