def max_sum_increasing_subsequence(nums, n):
    # Initialize a list to store the maximum sum for each element
    max_sum = [0] * n
    # Since every element is a subsequence of itself, the maximum sum for each element is 1
    for i in range(n):
        max_sum[i] = 1
    # Update the max_sum list for each element
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                max_sum[i] = max(max_sum[i], max_sum[j] + 1)
    # The maximum sum of the maximum increasing subsequence is the maximum value in max_sum
    return max(max_sum)
