    for i in range(1, n):
        for j in range(i):
            # If A[i] is greater than A[j] and dp[i] can be extended, update dp[i]
            if A[i] > A[j] and dp[i] < dp[j] + A[i]:
                dp[i] = dp[j] + A[i]

    # Find the maximum value in the dp list to get the maximum sum of increasing subsequence
    return max(dp)
