    # Check if the month is valid
    if month < 1 or month > 12:
        return False
    # Check if the day varies by month
    if month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month == 2:
        # Check for a leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False
    return True

