def coin_change(coins, total, amount):
    # Importing the functools module to memoize the results
    from functools import lru_cache

    @lru_cache(None)
    def helper(remaining, coin_index):
        # Base case: if remaining amount is 0, return 1
        if remaining == 0:
            return 1
        # Base case: if there are no more coins or no remaining amount, return 0
        if coin_index == len(coins) or remaining < 0:
            return 0
        # Recursive case: count by taking the current coin or not
        return helper(remaining - coins[coin_index], coin_index) + helper(remaining, coin_index + 1)

    # Starting the recursive helper function with the total amount and the first coin
    return helper(amount, 0)
