def find_First_Missing(arr, start, end):
    # Use the cyclic sort to place each element at its correct index
    for i in range(start, end + 1):
        # Find the correct position for the element arr[i]
        correct_index = arr[i]
        # If the element is within the range and not at its correct position
        if start <= correct_index <= end and arr[correct_index] != correct_index:
            # Swap the element with the element at its correct position
            arr[correct_index], arr[i] = arr[i], arr[correct_index]
        else:
            # If the element is out of range or at its correct position, move to the next element
            continue
    # After the cyclic sort, the first missing number is the index of the first element that is out of its correct position
    for i in range(start, end + 1):
        if arr[i] != i:
            return i
    # If all elements are in their correct positions, the missing number is the highest element plus one
    return end + 1
