def find_longest_conseq_subseq(nums, n):
    # Dictionary to keep track of numbers that have been processed
    num_dict = {}
    for num in nums:
        num_dict[num] = True

    longest_seq = 0
    for num in num_dict:
        if num - 1 not in num_dict:
            current_num = num
            current_seq = 1
            # Increment the sequence length for consecutive numbers
            while current_num + 1 in num_dict:
                current_num += 1
                current_seq += 1
            # Update the longest sequence found
            longest_seq = max(longest_seq, current_seq)

    return longest_seq
```

