def find_Min_Swaps(binary_array, n):
    # Initialize total swap count to zero
    total_swaps = 0

    # Iterate through the array up to the second last element
    for i in range(n - 1):
        # If the current element is 0, look for the first 1 to its right
        if binary_array[i] == 0:
            j = i + 1
            while j < n and binary_array[j] == 0:
                j += 1
            # If a 1 is found, calculate the number of swaps needed
            if j < n:
                total_swaps += (j - i - 1)

    return total_swaps
