def super_seq(s1, s2, m, n):
    # Create a 2D array to store lengths of longest common subsequences
    lis = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the lis table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                lis[i][j] = lis[i - 1][j - 1] + 1
            else:
                lis[i][j] = max(lis[i - 1][j], lis[i][j - 1])

    # The length of the supersequence is the sum of lengths of s1 and s2 minus the length of the longest common subsequence
    return m + n - lis[m][n]
```

