def check_min_heap(arr, root):
    # Base case: if the node is not a leaf node (i.e., it is a leaf node),
    # it is considered to be a min heap by default.
    if root >= len(arr) // 2:
        return True
    # Check if the current node is smaller than its children.
    if (root * 2 + 1 < len(arr) and arr[root] > arr[root * 2 + 1]) or (root * 2 + 2 < len(arr) and arr[root] > arr[root * 2 + 2]):
        return False
    # Recursively check the left and right subtrees.
    return check_min_heap(arr, root * 2 + 1) and check_min_heap(arr, root * 2 + 2)
```

