    even_count = 0
    # Loop through the array to count odd and even numbers
    for i in range(n):
        if i % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    # Calculate the index to find the kth number
    if k <= odd_count:
        # If k is within the range of odd numbers, return the kth odd number
