    odd_count, even_count = 0, 0
    # Iterate through the array to count odd and even elements
    for i in range(n):
        if i % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    # Check if k is within the valid range
    if k > odd_count:
        return "Out of Range"
    # Find the kth element based on its position
    if k <= even_count:
        # Calculate the kth even element
        return even_count + (k - 1)
    else:
        # Calculate the (k - even_count)th odd element
