def find_Min_Sum(n):
    # Initialize the minimum sum to a large number
    min_sum = float('inf')
    # Iterate through all possible factors of n
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            # Calculate the sum of the factor pair
            if i == n // i:
                min_sum = min(min_sum, i)
            else:
                min_sum = min(min_sum, i + n // i)
    return min_sum
