def rgb_to_hsv(r, g, b):
    # Normalize RGB values to the range [0, 1]
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    diff = max_color - min_color

    if max_color == 0:
        h = 0
    elif max_color == r:
        h = ((g - b) / diff) % 6
    elif max_color == g:
        h = ((b - r) / diff) + 2
    elif max_color == b:
        h = ((r - g) / diff) + 4

    h *= 60

    if max_color == 0:
        s = 0
    else:
        s = (diff / max_color) * 100

    v = max_color * 100

    return (h, s, v)
```

