def generate_matrix(n):
    # Initialize the matrix with zeros
    matrix = [[0] * n for _ in range(n)]
    # Variables for the starting point and direction
    start_x, start_y = 0, 0
    direction = 0  # 0 - right, 1 - down, 2 - left, 3 - up
    count = 1

    while count <= n * n:
        # Fill the current row in the current direction
        for i in range(n):
            matrix[start_x][start_y] = count
            count += 1
            if direction == 0:
                start_y += 1
            elif direction == 1:
                start_x += 1
            elif direction == 2:
                start_y -= 1
            elif direction == 3:
                start_x -= 1
        # Change direction after completing the current row
        direction = (direction + 1) % 4

        # If we have reached the boundary, adjust direction
        if direction == 0:
            if start_y < n - 1:
                start_y += 1
            else:
                direction = 1
        elif direction == 1:
            if start_x < n - 1:
                start_x += 1
            else:
                direction = 2
        elif direction == 2:
            if start_y > 0:
                start_y -= 1
            else:
                direction = 3
        elif direction == 3:
            if start_x > 0:
                start_x -= 1
            else:
                direction = 0

    return matrix
```

