def longest_increasing_subsequence(seq):
    if not seq:
        return 0

    # Initialize a list to store the length of the longest increasing subsequence at each index
    lis = [1] * len(seq)

    # Compute the length of the longest increasing subsequence for each element
    for i in range(1, len(seq)):
        for j in range(i):
            if seq[i] > seq[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Return the maximum value in the lis list, which represents the length of the longest increasing subsequence
    return max(lis)
