def is_triangleexists(a, b, c):
    # Check if all angles are positive
    if a <= 0 or b <= 0 or c <= 0:
        return False
    # Check if the sum of all angles is 180 degrees
    if a + b + c != 180:
        return False
    # Check the triangle inequality theorem
    if a + b > c and a + c > b and b + c > a:
        return True
    return False
