def prime_num(n):
    # Check for numbers less than 2
    if n < 2:
        return False
    # Iterate from 2 to the square root of n
    for i in range(2, int(n**0.5) + 1):
        # If n is divisible by i, it's not prime
        if n % i == 0:
            return False
    # If no divisors are found, n is prime
    return True
```

