def check(arr, n):
    # If the array has less than 3 elements, it can be sorted
    if n < 3:
        return True
    # Find the first element that is greater than its next element
    for i in range(n-1):
        if arr[i] > arr[i+1]:
            # Check if the array before this segment is sorted
            if (i+1) == 0 or arr[i] <= arr[i-1]:
                continue
            # Check if the array after this segment is sorted
            for j in range(i+1, n):
                if arr[j] < arr[j-1]:
                    return False
            return True
    return True
