def find_combinations(tup_list):
    def is_combinationPossible(combination, target):
        return sum(combination) == target

    combinations = set()
    for i in range(len(tup_list)):
        for j in range(i + 1, len(tup_list)):
            for k in range(j + 1, len(tup_list)):
                combination = tuple(sorted([tup_list[i][0], tup_list[j][0], tup_list[k][0]]))
