def rgb_to_hsv(r, g, b):
    # Convert RGB to HSV
    max_color = max(r, g, b)
    min_color = min(r, g, b)
    diff = max_color - min_color

    if max_color == min_color:
        h = 0
    elif max_color == r:
        h = (60 * ((g - b) / diff)) % 360
    elif max_color == g:
        h = (60 * ((b - r) / diff)) + 120
    else:
        h = (60 * ((r - g) / diff)) + 240

    s = 0 if max_color == 0 else (diff / max_color) * 100
    v = max_color * 100

