def modular_sum(arr, n, m):
    # Create a 2D array to store intermediate results
    t = [[False for _ in range(m+1)] for _ in range(n+1)]

    # Initialize the first row and first column of the table
    t[0][0] = True
    for i in range(1, m+1):
        t[0][i] = False
    for i in range(1, n+1):
        t[i][0] = True

    # Fill the table
    for i in range(1, n+1):
        for j in range(1, m+1):
            if j < arr[i-1]:
                t[i][j] = t[i-1][j]
            else:
                t[i][j] = t[i-1][j] or t[i-1][j-arr[i-1]]

    # Check if there exists a subset with sum divisible by m
    return t[n][m]
