def search_literal(text, pattern):
    # Initialize the starting position and the position of the pattern within the text
    start_position = 0
    pattern_position = 0

    # Loop through the text
    while start_position < len(text) and pattern_position < len(pattern):
        # If the current characters match, move both pointers forward
        if text[start_position] == pattern[pattern_position]:
            start_position += 1
            pattern_position += 1
        # If no match is found, move the starting pointer forward
        else:
            start_position += 1

    # If the pattern is not found, return -1, -1
    if pattern_position == len(pattern):
        return (start_position - len(pattern), start_position)
    else:
        return (-1, -1)

