def divisors(num):
    # Start with a list of potential divisors
    divisors = []
    # Iterate through possible divisors up to the square root of the number
    for i in range(1, int(math.sqrt(num)) + 1):
        # Check if i divides num
        if num % i == 0:
            # Add both divisors to the list
            divisors.append(i)
            if i != num // i:
                divisors.append(num // i)
    # Return the sorted list of divisors
    return sorted(divisors)
