def find_triplet_array(arr, n, k):
    # Iterate through the array to fix the first element of the triplet
    for i in range(n - 2):
        # Initialize two pointers for the remaining part of the array
        left, right = i + 1, n - 1
        # Move the pointers towards each other to find the triplet
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            # If the sum of the triplet equals k, return the triplet
            if current_sum == k:
                return (arr[i], arr[left], arr[right])
            # If the sum is less than k, move the left pointer to the right
            elif current_sum < k:
                left += 1
            # If the sum is greater than k, move the right pointer to the left
            else:
                right -= 1
    # If no triplet is found, return None
