def find_Diff(arr, n):
    frequency = {}  # Dictionary to store the frequency of each element

    # Calculate the frequency of each element in the array
    for i in range(n):
        if arr[i] in frequency:
            frequency[arr[i]] += 1
        else:
            frequency[arr[i]] = 1

    # Find the maximum and minimum frequencies
    min_freq = float('inf')
    max_freq = float('-inf')

    for freq in frequency.values():
        if freq < min_freq:
            min_freq = freq
        if freq > max_freq:
            max_freq = freq

    # Calculate the difference between the maximum and minimum frequencies
    return max_freq - min_freq
