def sum_Of_product(n):
    # Initialize the sum to 0
    total_sum = 0
    # Calculate the sum using the binomial coefficient formula
    for i in range(n + 1):
        total_sum += factorial(n) // (factorial(i) * factorial(n - i))
    return total_sum

