def min_Jumps(d, r, target):
    # If the target is the origin, no jumps are required
    if target == (0, 0):
        return 0
    # If the distance required to reach (d, 0) exceeds the reach of any one segment, it's not possible
    if r < d:
        return float('inf')
    # Initialize the number of jumps
    jumps = 0
    # If 'r' is greater than or equal to 'd', calculate the number of jumps
    if r >= d:
        jumps = (d + r - 1) // r  # Equivalent to (r * d + 1) // r
    return jumps
```

